/// GOAL #28 (issue #2416 review round 2): the deferred-mount path for a
/// DIRECT model call to a tool the partition keeps out of the manifest.
/// Mounts the tool live and returns it so the call proceeds natively
/// (real name, real approval tier, real executor — I2); null keeps the
/// plain not-found semantics for disabled, capability-absent, and
/// unknown names (I3: `off` beats everything).
Future<AgentTool?> resolveDeferredToolForCall(String name) async {
  final resolution = _toolGate.resolution;
  if (resolution == null) return null;
  final id = _toolGate.availabilityIdOf(name) ?? toolAvailabilityIdOf(name);
  if (id != null && !_enabledId(resolution, id)) return null;
  // A tool mounted EARLIER in this run has left the discoverable set —
  // but the run's in-flight context snapshot still misses it (the
  // snapshot copies state.tools at run start). Resolve through the LIVE
  // REGISTRY membership first — registry presence = mounted and
  // enabled (issue #2416 CI round 3, second-rewind probe). The gate's
  // originalTool() is NOT enough here: it hands back unmounted tools,
  // whose calls would die on the executor's deferred tombstone.
  final Tool? live = _toolRegistry.tools
      .where((t) => t.name == name)
      .firstOrNull;
  if (live != null) return live as AgentTool;
  if (_toolGate.discoverableToolNames.isEmpty) return null;
  if (!_toolGate.discoverableToolNames.contains(name)) return null;
  _mountDeferred([name]);
  return _toolGate.originalTool(name);
}

/// The I4 doc bytes of [tool]: its `description` plus the compact
/// `jsonEncode(parameters)` — the same bytes the providers serialize
/// and the ledger's manifest entry captures.
String _toolDocBytes(AgentTool tool) =>
    '${tool.description}\n${jsonEncode(tool.parameters)}';

/// Whether availability [id] is enabled under [resolution] — the gate's
/// own rule, replicated for the disabled tombstone (the gate's
/// per-server MCP map governs `mcp:<server>` families).
bool _enabledId(ToolAvailabilityResolution resolution, String id) {
  const mcpPrefix = 'mcp:';
  final resolved = resolution.byId[id];
  if (resolved != null) return resolved.enabled;
  if (id.startsWith(mcpPrefix)) {
    final server = id.substring(mcpPrefix.length);
    final declared = resolution.mcpServers[server];
    if (declared != null) return declared;
    return resolution.byId['mcp']?.enabled ?? true;
  }
  return true;
}

/// The disabled tombstone's why-text for [id]: the per-id reason, else
/// the aggregate `mcp` reason (the kill-switch), else a config-disabled
/// fallback for per-server disables.
String _disabledIdReason(ToolAvailabilityResolution resolution, String id) {
  return resolution.byId[id]?.reason ??
      resolution.byId['mcp']?.reason ??
      'disabled by config';
}

